function metric(label,value,detail=''){const div=document.createElement('div');div.className='metric';const span=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small');span.textContent=label;strong.textContent=value;small.textContent=detail;div.append(span,strong,small);return div;}
