 if(kind==='reference'&&!S.reference)throw Error('Import or draw a reference first.');
 const canvas=document.createElement('canvas');canvas.width=S.source.width;canvas.height=S.source.height;const c=canvas.getContext('2d');
 if(kind==='overlay'||kind==='cutout')c.drawImage(S.source,0,0);
 if(kind==='overlay'||kind==='boundary'){c.strokeStyle='#0a3024';c.lineWidth=5;c.lineJoin='round';c.stroke(new Path2D(selectedPath()));c.strokeStyle='#27e6a5';c.lineWidth=2.5;c.stroke(new Path2D(selectedPath('outer')));c.strokeStyle='#f299c5';c.lineWidth=2;c.setLineDash([6,4]);c.stroke(new Path2D(selectedPath('hole')));}
 else{const mask=kind==='reference'?S.reference:S.mask,pixels=kind==='cutout'?c.getImageData(0,0,canvas.width,canvas.height):c.createImageData(canvas.width,canvas.height);for(let i=0;i<mask.length;i++){if(kind==='cutout'){if(!mask[i])pixels.data[i*4+3]=0;}else{const v=mask[i]?255:0;pixels.data[i*4]=pixels.data[i*4+1]=pixels.data[i*4+2]=v;pixels.data[i*4+3]=255;}}c.putImageData(pixels,0,0);}
