 const c=layer.getContext('2d');c.save();c.globalCompositeOperation=painting?'source-over':'destination-out';c.strokeStyle=c.fillStyle=reference?'#ffb255':'#28e6a5';c.lineWidth=radius*2;c.lineCap='round';c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();c.beginPath();c.arc(b.x,b.y,radius,0,Math.PI*2);c.fill();c.restore();
