$('loadReference').onclick=()=>$('referenceFile').click();$('referenceFile').onchange=action(async()=>{const file=$('referenceFile').files[0];if(!file)return;const canvas=await readImage(file);if(canvas.width!==stage.width||canvas.height!==stage.height)throw Error('Reference PNG dimensions must exactly match the original image.');checkpoint();const p=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data;S.reference=new Uint8Array(stage.width*stage.height);for(let i=0;i<S.reference.length;i++)S.reference[i]=p[i*4+3]>127&&(p[i*4]+p[i*4+1]+p[i*4+2])/3>127?1:0;S.referenceVerified=false;$('verifiedReference').checked=false;S.benchmark=null;refreshLayers();renderBenchmark();draw();changed();say('Reference imported. Verify it manually, then check the verification box.');$('referenceFile').value='';});
$('blankReference').onclick=()=>{checkpoint();S.reference=new Uint8Array(stage.width*stage.height);S.referenceVerified=false;$('verifiedReference').checked=false;$('editReference').checked=true;$('view').value='reference';setTool('paint');S.benchmark=null;refreshLayers();renderBenchmark();draw();changed();say('Paint the reference manually. It is separate from the predicted mask.');};
